package org.springframework.samples.petclinic.acceptance;

import java.time.DayOfWeek;
import java.time.LocalDate;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import tools.jackson.databind.node.ObjectNode;

/** business-day: the EFFECTIVE registration date (supplied or defaulted) must fall on a business
 * day; a Saturday or Sunday rolls forward to the next Monday, and every value derived from the
 * registration date uses that adjusted date. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreDefaultDateIsBusinessDay() throws Exception {
		int id = createOwnerOk(ownerNode());
		DayOfWeek dow = LocalDate.parse(fetchOwner(id).get("registrationDate").asText()).getDayOfWeek();
		assertTrue(dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY, dow.toString());
	}

	@Test
	void suppliedSaturdayRollsForwardToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-08-15"); // Saturday
		int id = createOwnerOk(o);
		assertEquals("2026-08-17", fetchOwner(id).get("registrationDate").asText()); // Monday
	}

	@Test
	void suppliedSundayRollsForwardToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-08-16"); // Sunday
		int id = createOwnerOk(o);
		assertEquals("2026-08-17", fetchOwner(id).get("registrationDate").asText()); // Monday
	}

	@Test
	void suppliedWeekdayIsUnchanged() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-06-15"); // Monday
		int id = createOwnerOk(o);
		assertEquals("2026-06-15", fetchOwner(id).get("registrationDate").asText());
	}

	@Test
	void membershipNumberYearUsesAdjustedDate() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2022-12-31"); // Saturday, rolls to Monday 2023-01-02
		int id = createOwnerOk(o);
		var owner = fetchOwner(id);
		assertEquals("2023-01-02", owner.get("registrationDate").asText());
		// YY segment must be '23' (adjusted year), not '22' (supplied year).
		assertTrue(owner.get("membershipNumber").asText().endsWith("-M23"),
				owner.get("membershipNumber").asText());
	}

	@Test
	void weekendAndMondayCreatesShareTheSameBusinessDay() throws Exception {
		// The per-day create-limit buckets owners by their adjusted business day, so an owner
		// dated a Saturday and one dated the following Monday must land on the same stored date.
		ObjectNode sat = ownerNode();
		sat.put("registrationDate", "2026-08-15"); // Saturday
		ObjectNode mon = ownerNode();
		mon.put("registrationDate", "2026-08-17"); // Monday
		String satDate = fetchOwner(createOwnerOk(sat)).get("registrationDate").asText();
		String monDate = fetchOwner(createOwnerOk(mon)).get("registrationDate").asText();
		assertEquals(monDate, satDate);
		assertEquals("2026-08-17", satDate);
	}
}

